async function answerFrame(ws: WebSocket, session: ChatSession, validation: ValidationResult, sessionStore?: SessionStore): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
