// Does a pong sent for frame 2 beat an await-resumed answer to frame 1,
// when the client sends both frames back to back?
const {WebSocket, WebSocketServer} = require('ws');

const wss = new WebSocketServer({port: 0});
let receivedInOneChunk = 0;

wss.on('connection', ws => {
  let inChunk = 0;
  ws.on('message', raw => {
    const frame = JSON.parse(String(raw));
    inChunk += 1;
    if (frame.type === 'list') {
      Promise.reject(new Error('database offline')).catch(() => {
        ws.send(JSON.stringify({type: 'error'}));
      });
    }
    if (frame.type === 'ping') {
      ws.send(JSON.stringify({type: 'pong'}));
      // End of this data-event turn, as far as a handler can know.
      Promise.resolve().then(() => {
        if (inChunk > 1) receivedInOneChunk += 1;
        inChunk = 0;
      });
    }
  });
});

wss.on('listening', () => {
  const {port} = wss.address();
  const ws = new WebSocket(`ws://127.0.0.1:${port}`);
  const order = [];
  ws.on('open', () => {
    ws.send(JSON.stringify({type: 'list'}));
    ws.send(JSON.stringify({type: 'ping'}));
  });
  ws.on('message', raw => order.push(JSON.parse(String(raw)).type));
  setTimeout(() => {
    console.log('client received order:', order.join(', '));
    console.log('runs where both frames landed in one data event:', receivedInOneChunk);
    process.exit(0);
  }, 300);
});

