async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore: SessionStore | undefined
): Promise<void> {
  if (!validation.valid) {
    refuseFrame(ws, validation);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  // Off the turn lock: a history request is not a turn and must not queue behind a streaming answer.
  if (message.type === 'list_sessions') await answerListSessions(ws, session, message, sessionStore);
}

// The list is the connection's own: the user id comes from the session, never from the frame.
async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: ListSessionsMessage,
  sessionStore: SessionStore | undefined
): Promise<void> {
  try {
